package com.printflow;
import com.printflow.identity.CustomerMail;import org.junit.jupiter.api.Test;import org.springframework.mock.env.MockEnvironment;import org.springframework.jdbc.core.JdbcTemplate;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class LocalMailConfigurationTest {
 CustomerMail config(String profile,String base,String allowed,String after){var env=new MockEnvironment();env.setActiveProfiles(profile);return new CustomerMail(mock(JdbcTemplate.class),"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",true,"smtp.gmail.com",587,"sender@jdprintex.in","private-placeholder",base,allowed,after,env);}
 @Test void devRequiresExplicitRecipientAndActivationBoundary(){assertThrows(IllegalStateException.class,()->config("dev","http://127.0.0.1:3000","",""));assertDoesNotThrow(()->config("dev","http://127.0.0.1:3000","test@jdprintex.in","2026-10-24T00:00:00Z"));}
 @Test void loopbackExceptionDoesNotPermitProductionOrRemoteHttp(){assertThrows(IllegalStateException.class,()->config("prod","http://127.0.0.1:3000","test@jdprintex.in","2026-10-24T00:00:00Z"));assertThrows(IllegalStateException.class,()->config("dev","http://jdprintex.in","test@jdprintex.in","2026-10-24T00:00:00Z"));}
 @Test void historicalBoundaryAndNonAllowedRecipientsAreHeldWithoutSending(){var db=mock(JdbcTemplate.class);var env=new MockEnvironment();env.setActiveProfiles("dev");var first=java.util.UUID.randomUUID();var second=java.util.UUID.randomUUID();when(db.queryForList(org.mockito.ArgumentMatchers.anyString())).thenReturn(java.util.List.of(java.util.Map.of("id",first,"recipient","fixture@example.test"),java.util.Map.of("id",second,"recipient","other@jdprintex.in")));var mail=new CustomerMail(db,"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",true,"smtp.gmail.com",587,"sender@jdprintex.in","private-placeholder","http://127.0.0.1:3000","chosen@jdprintex.in","2026-10-24T00:00:00Z",env);mail.dispatch();verify(db).update("update mail_outbox set state='HELD' where state='PENDING' and created_at<?",java.sql.Timestamp.from(java.time.Instant.parse("2026-10-24T00:00:00Z")));verify(db).update("update mail_outbox set state='HELD' where id=?",first);verify(db).update("update mail_outbox set state='HELD' where id=?",second);}

 @Test void systemCredentialsAndMisspelledAliasWorkWithoutAppCredentialCopies(){for(String name:java.util.List.of("SPRING_MAIL_PASSWORD","SPRING_MAIL_PASSWROD")){var env=new MockEnvironment().withProperty("SPRING_MAIL_USERNAME","sender@jdprintex.in").withProperty(name,"private-placeholder");env.setActiveProfiles("dev");assertDoesNotThrow(()->new CustomerMail(mock(JdbcTemplate.class),"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",true,"smtp.gmail.com",587,"","","http://127.0.0.1:3000","chosen@jdprintex.in","2026-10-24T00:00:00Z",env));}}

}
